import logging
from fastapi import Request, FastAPI
from fastapi.responses import JSONResponse
from fastapi.exceptions import RequestValidationError
from app.models.response_models import ApiResponse

logger = logging.getLogger("app.exception_handlers")

# Standardized Exception Definitions for Custom Business Logic Errors
class OCRServiceException(Exception):
    """Base exception class for all custom errors generated by our OCR system."""
    def __init__(self, message: str, error_code: str, status_code: int = 400):
        super().__init__(message)
        self.message = message
        self.error_code = error_code
        self.status_code = status_code


class FileTooLargeException(OCRServiceException):
    def __init__(self, message: str = "Uploaded file size exceeds the allowed threshold."):
        super().__init__(message, "FILE_TOO_LARGE", 413)


class InvalidImageTypeException(OCRServiceException):
    def __init__(self, message: str = "Unsupported image format or MIME type."):
        super().__init__(message, "INVALID_IMAGE_TYPE", 415)


class CorruptedImageException(OCRServiceException):
    def __init__(self, message: str = "Image file is empty, truncated, or corrupted."):
        super().__init__(message, "CORRUPTED_IMAGE", 400)


class SegmentationFailureException(OCRServiceException):
    def __init__(self, message: str):
        super().__init__(message, "SEGMENTATION_FAILURE", 422)


class OCRProviderFailureException(OCRServiceException):
    def __init__(self, message: str):
        super().__init__(message, "OCR_PROVIDER_FAILURE", 502)


class AzureTimeoutException(OCRServiceException):
    def __init__(self, message: str = "Connecting to Azure Vision services timed out."):
        super().__init__(message, "AZURE_TIMEOUT", 504)


def register_exception_handlers(app: FastAPI) -> None:
    """Registers standard handlers on a FastAPI application instance."""

    @app.exception_handler(OCRServiceException)
    async def ocr_custom_handler(request: Request, exc: OCRServiceException):
        logger.error(
            "OCRCustomError - RequestID: %s - ErrorCode: %s - Message: %s",
            getattr(request.state, "request_id", "N/A"), exc.error_code, exc.message
        )
        response_data = ApiResponse(
            success=False,
            message=exc.message,
            data={"error_code": exc.error_code}
        )
        return JSONResponse(
            status_code=exc.status_code,
            content=response_data.model_dump()
        )

    @app.exception_handler(RequestValidationError)
    async def validation_error_handler(request: Request, exc: RequestValidationError):
        logger.error(
            "ValidationError - RequestID: %s - Details: %s",
            getattr(request.state, "request_id", "N/A"), str(exc.errors())
        )
        # Re-pack errors nicely
        errs = []
        cleaned_details = []
        for e in exc.errors():
            loc = ".".join(str(x) for x in e.get("loc", []))
            errs.append(f"{loc}: {e.get('msg', '')}")
            
            # Clean non-serializable exception objects from ctx dictionary elements
            cleaned_e = dict(e)
            if "ctx" in cleaned_e and isinstance(cleaned_e["ctx"], dict):
                cleaned_ctx = {}
                for ck, cv in cleaned_e["ctx"].items():
                    if isinstance(cv, Exception):
                        cleaned_ctx[ck] = str(cv)
                    else:
                        try:
                            import json
                            json.dumps(cv)
                            cleaned_ctx[ck] = cv
                        except Exception:
                            cleaned_ctx[ck] = str(cv)
                cleaned_e["ctx"] = cleaned_ctx
            cleaned_details.append(cleaned_e)
        
        message = "; ".join(errs)
        response_data = ApiResponse(
            success=False,
            message=f"Validation failed: {message}",
            data={"error_code": "VALIDATION_ERROR", "details": cleaned_details}
        )
        return JSONResponse(
            status_code=400,
            content=response_data.model_dump()
        )



    @app.exception_handler(Exception)
    async def generic_error_handler(request: Request, exc: Exception):
        logger.exception(
            "ServerError - RequestID: %s - Exception: %s",
            getattr(request.state, "request_id", "N/A"), str(exc)
        )
        response_data = ApiResponse(
            success=False,
            message="An unexpected server error occurred.",
            data={"error_code": "INTERNAL_SERVER_ERROR"}
        )
        return JSONResponse(
            status_code=500,
            content=response_data.model_dump()
        )
